function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPnaReceipts(
  query: Record<string, string | number | boolean>,
): Promise<PnaReceiptListItem[]> {
  const res = await apiClient.get<BffResponse<PnaReceiptListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPnaReceipt(sttRec: string): Promise<PnaReceipt> {
  const res = await apiClient.get<BffResponse<PnaReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createPnaReceipt(body: PnaReceiptWrite): Promise<PnaReceipt> {
  const res = await apiClient.post<BffResponse<PnaReceipt>>(BASE, body);
  return unwrap(res);
}

export async function updatePnaReceipt(sttRec: string, body: PnaReceiptWrite): Promise<PnaReceipt> {
  const res = await apiClient.put<BffResponse<PnaReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
